<?php require_once __DIR__.'/../app/Database.php'; require_once __DIR__.'/../app/Mailer.php'; require_once __DIR__.'/../app/Security.php';
if($_SERVER['REQUEST_METHOD']!=='POST') exit; $name=trim($_POST['name']??'');$email=trim($_POST['email']??'');$message=trim($_POST['message']??''); if(!$name||!filter_var($email,FILTER_VALIDATE_EMAIL)||!$message) exit('Data tidak valid.');
$st=Database::pdo()->prepare('INSERT INTO messages(name,email,message) VALUES(?,?,?)');$st->execute([$name,$email,$message]); $s=setting('contact_email',''); if(!$s){$s=smtp_settings()['from_email']??'';} if($s){send_smtp($s,'New website inquiry from '.$name,'<h2>New Inquiry</h2><p><b>Name:</b> '.e($name).'</p><p><b>Email:</b> '.e($email).'</p><p>'.nl2br(e($message)).'</p>',$email);} header('Location: /#contact');
